async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let state = initial;
  let physicalLine = 0;
  let recordIndex = 0;
  let exhausted = false;
  let failed = false;
  let fragments = [];

  async function processLine(line) {
    physicalLine++;

    if (line.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex: recordIndex++
    });

    state = result.state;
    return result.done === true;
  }

  async function processText(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);
      if (end === -1) break;

      let line;
      if (fragments.length === 0) {
        line = text.slice(start, end);
      } else {
        fragments.push(text.slice(start, end));
        line = fragments.join("");
        fragments = [];
      }

      if (await processLine(line)) return true;
      start = end + 1;
    }

    if (start < text.length) {
      fragments.push(text.slice(start));
    }

    return false;
  }

  try {
    while (true) {
      const item = await iterator.next();

      if (item.done) {
        exhausted = true;
        break;
      }

      if (await processText(decoder.decode(item.value, { stream: true }))) {
        return state;
      }
    }

    if (await processText(decoder.decode())) {
      return state;
    }

    if (fragments.length > 0) {
      const line = fragments.join("");
      fragments = [];
      await processLine(line);
    }

    return state;
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!exhausted || failed) {
      const returnMethod = iterator.return;
      if (typeof returnMethod === "function") {
        await returnMethod.call(iterator);
      }
    }
  }
}
